/**
 * Customer identity helpers.
 *
 * There is no Customer table: a customer is derived from conversations. A customer is
 * identified, inside one organization, by the pair (channel type, customerId):
 *
 * - WHATSAPP   customerId = the sender's phone number (verified by WhatsApp)
 * - MESSENGER  customerId = page-scoped user id
 * - INSTAGRAM  customerId = Instagram-scoped user id
 * - WEBCHAT    customerId = visitor id generated by the widget (client supplied)
 *
 * The channel type is part of the key on purpose: a webchat visitor id is chosen by the
 * browser, so without it a visitor could pick someone's phone number as their visitor id
 * and be merged into that WhatsApp customer. Conversations of the same customerId on two
 * channels of the same type (e.g. two WhatsApp numbers of one org) ARE merged, because the
 * identifier is issued by the platform and means the same person.
 *
 * Customers are NOT merged across channel types: the only shared attributes (name, email,
 * phone typed into a form or guessed by the AI) are unverified, so merging on them could
 * attach one person's conversations and notes to another person's profile.
 *
 * The public id (`customerKey`) is `<prefix>_<base64url(customerId)>`, safe to use as a
 * single URL path segment whatever characters the raw customerId contains.
 */

export const CUSTOMER_CHANNEL_TYPES = ['WHATSAPP', 'MESSENGER', 'INSTAGRAM', 'WEBCHAT'] as const;
export type CustomerChannelType = (typeof CUSTOMER_CHANNEL_TYPES)[number];

const PREFIX_BY_TYPE: Record<CustomerChannelType, string> = {
  WHATSAPP: 'wa',
  MESSENGER: 'ms',
  INSTAGRAM: 'ig',
  WEBCHAT: 'wc',
};

const TYPE_BY_PREFIX: Record<string, CustomerChannelType> = {
  wa: 'WHATSAPP',
  ms: 'MESSENGER',
  ig: 'INSTAGRAM',
  wc: 'WEBCHAT',
};

/** Longest raw customerId we accept when decoding a key (defensive bound). */
const MAX_CUSTOMER_ID_LENGTH = 512;

export interface CustomerIdentity {
  channelType: CustomerChannelType;
  customerId: string;
}

export function encodeCustomerKey(channelType: CustomerChannelType, customerId: string): string {
  return `${PREFIX_BY_TYPE[channelType]}_${Buffer.from(customerId, 'utf8').toString('base64url')}`;
}

/** Returns null for anything that is not a well-formed customer key. */
export function decodeCustomerKey(key: string): CustomerIdentity | null {
  if (typeof key !== 'string') return null;
  const match = /^([a-z]{2})_([A-Za-z0-9_-]+)$/.exec(key);
  const prefix = match?.[1];
  const encoded = match?.[2];
  if (!prefix || !encoded) return null;

  const channelType = TYPE_BY_PREFIX[prefix];
  if (!channelType) return null;

  const customerId = Buffer.from(encoded, 'base64url').toString('utf8');
  if (!customerId || customerId.length > MAX_CUSTOMER_ID_LENGTH) return null;
  // Reject non-canonical encodings (and invalid UTF-8, which decodes to U+FFFD and so
  // does not round-trip): one customer has exactly one key.
  if (encodeCustomerKey(channelType, customerId) !== key) return null;

  return { channelType, customerId };
}

/** Escape LIKE/ILIKE wildcards so a search term is matched literally (escape char: backslash). */
export function escapeLikePattern(term: string): string {
  return term.replace(/[\\%_]/g, (ch) => `\\${ch}`);
}

/** Average rating rounded to 2 decimals, or null when there are no ratings. */
export function roundRating(avg: number | null | undefined): number | null {
  if (avg === null || avg === undefined || Number.isNaN(avg)) return null;
  return Math.round(avg * 100) / 100;
}
